use crate::engine::http_envelope::{
    RequestEnvelope, ResponseEnvelope, MAX_HANDLER_RESPONSE_BYTES,
};
use crate::engine::quickjs::QuickJsHandler;
use crate::error::EngineError;
use crate::synthesizer::ContractAssertion;

/// Result of evaluating a contract assertion against an isolated candidate handler.
#[derive(Debug, Clone)]
pub struct AssertionResult {
    pub name: String,
    pub passed: bool,
    pub actual_status: Option<u16>,
    pub expected_status: u16,
    pub error_message: Option<String>,
}

/// A fixed request owned by the host, not generated by the model or SPEC.
#[derive(Debug, Clone)]
struct HostProbe {
    name: &'static str,
    request: RequestEnvelope,
}

/// Adversarial ABI probes. They test that valid but unusual request envelopes do not
/// trap the guest or produce an invalid HTTP response envelope. They do not assert
/// application-specific status codes or business behavior.
fn host_probes() -> Vec<HostProbe> {
    use std::collections::HashMap;

    vec![
        HostProbe {
            name: "minimal request",
            request: RequestEnvelope {
                method: "GET".into(),
                path: "/__nosrc_probe__/minimal".into(),
                query: HashMap::new(),
                headers: HashMap::new(),
                body: None,
            },
        },
        HostProbe {
            name: "encoded path and adversarial query",
            request: RequestEnvelope {
                method: "GET".into(),
                path: "/__nosrc_probe__/encoded/%2e%2e/%2F".into(),
                query: HashMap::from([
                    ("empty".into(), String::new()),
                    ("reserved".into(), "&=/+%?#".into()),
                    ("unicode".into(), "雪だるま☃".into()),
                ]),
                headers: HashMap::from([
                    ("accept".into(), "application/json".into()),
                    ("x-nosrc-probe".into(), "quotes=\"; braces={}".into()),
                ]),
                body: None,
            },
        },
        HostProbe {
            name: "JSON body with escaped delimiters and Unicode",
            request: RequestEnvelope {
                method: "POST".into(),
                path: "/__nosrc_probe__/body".into(),
                query: HashMap::from([("mode".into(), "probe".into())]),
                headers: HashMap::from([(
                    "content-type".into(),
                    "application/json".into(),
                )]),
                body: Some(
                    r#"{"text":"quotes: \" and slash /","unicode":"こんにちは 🌍","nested":{"items":[1,true,null]}}"#
                        .into(),
                ),
            },
        },
    ]
}

/// Runs host-owned ABI probes on a disposable candidate instance. Passing these probes
/// establishes only that the candidate accepts the selected valid request envelopes and
/// returns syntactically valid, bounded HTTP responses. It does not establish endpoint
/// correctness, authorization, semantic security, or general robustness.
pub struct HostProbeVerifier;

impl HostProbeVerifier {
    pub fn evaluate_handler(&self, candidate: &mut QuickJsHandler) -> Vec<HostProbeResult> {
        host_probes()
            .into_iter()
            .map(|probe| {
                let result = match candidate.invoke(&probe.request) {
                    Ok(response) => validate_host_probe_response(&response),
                    Err(error) => Err(format!("Candidate execution failed: {error}")),
                };
                HostProbeResult {
                    name: probe.name.to_string(),
                    passed: result.is_ok(),
                    error_message: result.err(),
                }
            })
            .collect()
    }
}

#[derive(Debug, Clone)]
pub struct HostProbeResult {
    pub name: String,
    pub passed: bool,
    pub error_message: Option<String>,
}

fn validate_host_probe_response(response: &ResponseEnvelope) -> Result<(), String> {
    if !(100..=599).contains(&response.status) {
        return Err(format!(
            "Response status {} is outside the valid HTTP range",
            response.status
        ));
    }

    // The ABI permits an omitted/null body, represented as None, or a UTF-8 string.
    // The serde decode in QuickJsHandler::invoke rejects every other JSON type; keep
    // the byte-size check explicit here so the host-probe guarantee does not depend
    // only on that lower-level response-envelope limit.
    if let Some(body) = &response.body {
        if body.len() > MAX_HANDLER_RESPONSE_BYTES {
            return Err(format!(
                "Response body exceeds the {MAX_HANDLER_RESPONSE_BYTES} byte limit"
            ));
        }
    }

    for (name, value) in &response.headers {
        axum::http::header::HeaderName::from_bytes(name.as_bytes())
            .map_err(|_| format!("Response contains an invalid header name: {name:?}"))?;
        axum::http::header::HeaderValue::try_from(value.as_str())
            .map_err(|_| format!("Response contains an invalid value for header {name:?}"))?;
    }

    Ok(())
}

/// Runs the complete assertion suite against one isolated candidate instance.
///
/// All assertions share the candidate instance so module-scoped JavaScript state
/// behaves exactly as it will across requests after activation. The caller must
/// instantiate a fresh production handler after verification succeeds.
pub struct ShadowVerifier;

impl ShadowVerifier {
    pub fn new() -> Self {
        Self
    }

    pub fn evaluate_handler(
        &self,
        candidate: &mut QuickJsHandler,
        assertions: &[ContractAssertion],
    ) -> Result<Vec<AssertionResult>, EngineError> {
        if assertions.is_empty() {
            return Err(EngineError::Internal(
                "Shadow verification requires at least one contract assertion".into(),
            ));
        }

        let mut results = Vec::with_capacity(assertions.len());
        for assertion in assertions {
            match candidate.invoke(&assertion.request) {
                Ok(response) => {
                    let (passed, error_message) = evaluate_response(&response, assertion);
                    results.push(AssertionResult {
                        name: assertion.name.clone(),
                        passed,
                        actual_status: Some(response.status),
                        expected_status: assertion.expected_status,
                        error_message,
                    });
                }
                Err(error) => results.push(AssertionResult {
                    name: assertion.name.clone(),
                    passed: false,
                    actual_status: None,
                    expected_status: assertion.expected_status,
                    error_message: Some(format!("Candidate execution failed: {error}")),
                }),
            }
        }

        for result in &results {
            tracing::debug!(
                assertion = %result.name,
                passed = result.passed,
                expected_status = result.expected_status,
                actual_status = ?result.actual_status,
                "Contract assertion evaluated"
            );
        }
        Ok(results)
    }

    pub fn verify_handler(
        &self,
        candidate: &mut QuickJsHandler,
        assertions: &[ContractAssertion],
    ) -> Result<Vec<AssertionResult>, EngineError> {
        let results = self.evaluate_handler(candidate, assertions)?;
        let failed: Vec<String> = results
            .iter()
            .filter(|result| !result.passed)
            .map(|result| {
                format!(
                    "{}: {}",
                    result.name,
                    result
                        .error_message
                        .as_deref()
                        .unwrap_or("assertion failed")
                )
            })
            .collect();

        if !failed.is_empty() {
            return Err(EngineError::Internal(format!(
                "Candidate verification failed: {}",
                failed.join("; ")
            )));
        }
        Ok(results)
    }
}

impl Default for ShadowVerifier {
    fn default() -> Self {
        Self::new()
    }
}

fn evaluate_response(
    response: &ResponseEnvelope,
    assertion: &ContractAssertion,
) -> (bool, Option<String>) {
    if response.status != assertion.expected_status {
        return (
            false,
            Some(format!(
                "Expected status {}, got {}",
                assertion.expected_status, response.status
            )),
        );
    }

    if let Some(expected_substring) = &assertion.body_contains {
        let body = response.body.as_deref().unwrap_or("");
        if !body.contains(expected_substring) {
            return (
                false,
                Some(format!(
                    "Body does not contain expected substring '{expected_substring}'. Actual: '{body}'"
                )),
            );
        }
    }

    if let Some(headers) = &assertion.header_matches {
        for (name, expected_value) in headers {
            let actual = response
                .headers
                .iter()
                .find(|(actual_name, _)| actual_name.eq_ignore_ascii_case(name))
                .map(|(_, value)| value);
            match actual {
                Some(actual_value) if actual_value == expected_value => {}
                Some(actual_value) => {
                    return (
                        false,
                        Some(format!(
                            "Header '{name}' value mismatch: expected '{expected_value}', got '{actual_value}'"
                        )),
                    );
                }
                None => {
                    return (
                        false,
                        Some(format!("Missing expected header '{name}' in response")),
                    );
                }
            }
        }
    }

    (true, None)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::engine::http_envelope::RequestEnvelope;
    use crate::engine::quickjs::{test_support, QuickJsEngine, DEFAULT_COMPONENT_FUEL};
    use std::collections::HashMap;

    fn assertion(expected_status: u16, body_contains: Option<&str>) -> ContractAssertion {
        ContractAssertion {
            name: "test assertion".to_string(),
            request: RequestEnvelope {
                method: "GET".to_string(),
                path: "/health".to_string(),
                query: HashMap::new(),
                headers: HashMap::new(),
                body: None,
            },
            expected_status,
            body_contains: body_contains.map(str::to_string),
            header_matches: None,
        }
    }

    #[test]
    fn host_probe_response_validation_accepts_an_omitted_body() {
        let response = ResponseEnvelope::new(204, None);
        assert!(validate_host_probe_response(&response).is_ok());
    }

    #[test]
    fn host_probe_response_validation_rejects_an_oversized_body() {
        let response = ResponseEnvelope::new(
            200,
            Some("x".repeat(MAX_HANDLER_RESPONSE_BYTES + 1)),
        );
        let error = validate_host_probe_response(&response).unwrap_err();
        assert!(error.contains("Response body exceeds the 1048576 byte limit"));
    }

    #[tokio::test]
    async fn host_probes_accept_a_handler_that_returns_valid_responses() {
        let (engine, compiled) = test_support::compiled().await;
        let mut candidate = engine
            .instantiate(compiled, DEFAULT_COMPONENT_FUEL)
            .unwrap();
        let results = HostProbeVerifier.evaluate_handler(&mut candidate);
        assert_eq!(results.len(), 3);
        assert!(results.iter().all(|result| result.passed), "{results:?}");
    }

    #[tokio::test]
    async fn host_probes_reject_a_candidate_that_traps_on_each_probe() {
        let engine = QuickJsEngine::new().unwrap();
        let source = r#"
            export function handle(requestJson) {
                const request = JSON.parse(requestJson);
                if (request.path.startsWith("/__nosrc_probe__/")) {
                    throw new Error("host probe rejected");
                }
                return JSON.stringify({ status: 200, headers: {}, body: "ok" });
            }
        "#;
        let compiled = engine.compile_handler(source).await.unwrap();
        let mut candidate = engine
            .instantiate(&compiled, DEFAULT_COMPONENT_FUEL)
            .unwrap();
        let results = HostProbeVerifier.evaluate_handler(&mut candidate);
        assert_eq!(results.len(), 3);
        assert!(results.iter().all(|result| !result.passed), "{results:?}");
        assert!(
            results.iter().all(|result| result
                .error_message
                .as_deref()
                .is_some_and(|message| message.contains("Candidate execution failed"))),
            "{results:?}"
        );
    }

    #[tokio::test]
    async fn verifier_approves_a_valid_javascript_candidate() {
        let (engine, compiled) = test_support::compiled().await;
        let mut candidate = engine
            .instantiate(compiled, DEFAULT_COMPONENT_FUEL)
            .unwrap();

        let results = ShadowVerifier::new()
            .verify_handler(&mut candidate, &[assertion(200, Some("healthy"))])
            .unwrap();

        assert_eq!(results.len(), 1);
        assert!(results[0].passed);
    }

    #[tokio::test]
    async fn verifier_enforces_expected_response_headers() {
        let (engine, compiled) = test_support::compiled().await;
        let mut candidate = engine
            .instantiate(compiled, DEFAULT_COMPONENT_FUEL)
            .unwrap();
        let mut expected = assertion(200, Some("healthy"));
        expected.header_matches = Some(HashMap::from([(
            "content-type".to_string(),
            "text/plain".to_string(),
        )]));

        let results = ShadowVerifier::new()
            .verify_handler(&mut candidate, &[expected])
            .unwrap();
        assert!(results[0].passed);

        let mut wrong_header = assertion(200, Some("healthy"));
        wrong_header.header_matches = Some(HashMap::from([(
            "content-type".to_string(),
            "application/json".to_string(),
        )]));
        assert!(ShadowVerifier::new()
            .verify_handler(&mut candidate, &[wrong_header])
            .is_err());
    }

    #[tokio::test]
    async fn verifier_passes_query_parameters_to_the_guest_handler() {
        let (engine, compiled) = test_support::compiled().await;
        let mut candidate = engine
            .instantiate(compiled, DEFAULT_COMPONENT_FUEL)
            .unwrap();
        let mut query_assertion = assertion(200, Some("rust wasm"));
        query_assertion.request.path = "/query".to_string();
        query_assertion.request.query = HashMap::from([("q".to_string(), "rust wasm".to_string())]);

        let results = ShadowVerifier::new()
            .verify_handler(&mut candidate, &[query_assertion])
            .unwrap();
        assert!(results[0].passed);
    }

    #[tokio::test]
    async fn verifier_rejects_an_empty_assertion_suite() {
        let (engine, compiled) = test_support::compiled().await;
        let mut candidate = engine
            .instantiate(compiled, DEFAULT_COMPONENT_FUEL)
            .unwrap();

        let error = ShadowVerifier::new()
            .verify_handler(&mut candidate, &[])
            .unwrap_err();

        assert!(error
            .to_string()
            .contains("at least one contract assertion"));
    }

    #[tokio::test]
    async fn verifier_rejects_a_candidate_that_fails_an_assertion() {
        let (engine, compiled) = test_support::compiled().await;
        let mut candidate = engine
            .instantiate(compiled, DEFAULT_COMPONENT_FUEL)
            .unwrap();
        let mut failing_assertion = assertion(200, None);
        failing_assertion.request.path = "/error".to_string();

        let result = ShadowVerifier::new().verify_handler(&mut candidate, &[failing_assertion]);

        assert!(result.is_err());
    }

    #[tokio::test]
    async fn assertions_share_candidate_module_state_in_order() {
        let (engine, compiled) = test_support::compiled().await;
        let mut candidate = engine
            .instantiate(compiled, DEFAULT_COMPONENT_FUEL)
            .unwrap();

        let mut first_request = assertion(200, None).request;
        first_request.path = "/counter".to_string();
        let second_request = first_request.clone();
        let first = ContractAssertion {
            name: "first call".to_string(),
            request: first_request,
            expected_status: 200,
            body_contains: Some("1".to_string()),
            header_matches: None,
        };
        let second = ContractAssertion {
            name: "second call".to_string(),
            request: second_request,
            expected_status: 200,
            body_contains: Some("2".to_string()),
            header_matches: None,
        };

        let results = ShadowVerifier::new()
            .verify_handler(&mut candidate, &[first, second])
            .unwrap();
        assert!(results.iter().all(|result| result.passed));
    }
}
